# Code generated by Claude
"""OBSOLETE (the zombie pose search is retired, A5; the pose is unchanged and the camera adapts to it; David 2026-10-22, M153, M162): the eagle camera is fixed to the torso and there is no neck. Kept until the B2.13 cleanup deletes it; it imports code that no longer exists and does not run.

Arm coverage of the eagle image for home poses at several stances (David 2026-10-20). Report only: nothing in the config is changed, no pose is applied.

    source .venv/bin/activate
    MUJOCO_GL=egl python experiments/home_pose_coverage.py [--variants rank2_straight] [--out data/home_pose_search/coverage]

Arm coverage is the share of the eagle camera's image (640 x 480, neck at its framing pose) covered by the robot's arms: every moving arm part from the first link on, the hands and fingers
included (src/stance_checks.OcclusionMeter, a segmentation render); the hands alone are reported too. It is a preference, not a requirement: the requirements (src/task_config.
STANCE_REQUIREMENTS) are listed beside it so that a pose is only compared where they are met.

Poses: A (the current one), the search's rank 1 and rank 2 (data/home_pose_search/evals.jsonl) and the variants named by --variants (data/home_pose_search/variants.json).
Stances (every pose at every stance): rank 2's own search stance and pedestal; rank 1's finder stance (data/home_pose_search/search_rank1_widest_range/); and, per variant, the stance its
finder run chose (data/home_pose_search/search_<variant>_coverage/), if that folder exists.
Writes coverage.png (the eagle images side by side, the arms tinted red; one row per stance, one column per pose), coverage.json and coverage.md (the table) under --out.
"""

import argparse
import gc
import json
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import cv2  # noqa: E402
import mujoco  # noqa: E402
import numpy as np  # noqa: E402

import home_pose_candidates as HPC  # noqa: E402
import home_pose_search as HPS  # noqa: E402
import stance_from_map as SFM  # noqa: E402
from home_pose_compare import put, tag, tolerance_fn  # noqa: E402
from src import robot_specs  # noqa: E402
from src.neck import set_neck_pose  # noqa: E402
from src.stance_checks import occlusion_ok  # noqa: E402
from src.task_config import STANCE_REQUIREMENTS as REQ  # noqa: E402

CELL = (480, 360)


def measure(ev, st, tol, search):
    """Everything about one pose at one stance, and the eagle image with the arms tinted."""
    chk, m = ev.chk, ev.m
    ns = chk.neck_spread(st)
    chk.place(st)
    d = chk.d
    set_neck_pose(m, d, robot_specs.NECK_SPECS, [ns["targets"][n] for n in robot_specs.NECK_SPECS["active_joints"]])
    mujoco.mj_forward(m, d)
    if chk.meter is None:
        from src.stance_checks import OcclusionMeter
        chk.meter = OcclusionMeter(m)
    oc = chk.meter.measure(d, masks=True)
    r = mujoco.Renderer(m, 480, 640)
    r.update_scene(d, camera="eagle_cam")
    img = r.render().copy()
    r.close()
    mask = oc.pop("arm_mask")
    img[mask] = (0.45 * img[mask] + 0.55 * np.array([255, 40, 40])).astype(np.uint8)
    fr = chk.framing_slack(st)
    hc = chk.home_clearance(st)
    pb = chk.beaker_on_hotplate_clearance(st)
    g = search.geometry(st)
    res = {"stance": [float(st[0]), float(st[1]), math.degrees(st[2]), float(st[3])], "arm_frac": oc["arm_frac"], "hand_frac": oc["hand_frac"], "beaker_hidden": oc["beaker_hidden_frac"],
           "hotplate_hidden": oc["hotplate_hidden_frac"], "framing_slack": fr["slack"], "framing_limit": fr["limit"], "home_clearance_mm": 1000 * hc["arms"], "placed_beaker_mm": None if pb is None else 1000 * pb,
           "neck_spread": ns["spread"], "tolerance_cm": 100 * tol(st[0], st[1], st[3]), "gripper_yaw_deg": g["yaw_deg"], "gripper_pitch_deg": g["pitch_deg"], "gripper_roll_deg": g["roll_deg"]}
    res["requirements_met"] = bool(res["home_clearance_mm"] >= 1000 * REQ["home_min_clearance"] and (pb is None or pb >= REQ["placed_beaker_min_clearance"]) and res["neck_spread"] <= REQ["neck_max_spread"]
                                   and occlusion_ok(oc) and res["framing_slack"] >= REQ["framing_min_slack"])
    return res, img


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("--out", default=str(PROJECT_ROOT / "data" / "home_pose_search" / "coverage"))
    ap.add_argument("--variants", nargs="*", default=[])
    args = ap.parse_args()
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    sd = PROJECT_ROOT / "data" / "home_pose_search"
    best = HPS.load_best(sd, 2)
    c0 = HPC.CURRENT_STANCE
    poses = [("A", list(HPC.CANDIDATES["A"]))] + [(f"rank {i + 1}", b["q_deg"]) for i, b in enumerate(best)]
    variants = HPS.load_variants(sd)
    poses += [(v, variants[v]["q_deg"]) for v in args.variants]
    r2 = best[1]
    stances = [("rank 2's search stance", (c0[0] + 0.01 * r2["offset_cm"][0], c0[1] + 0.01 * r2["offset_cm"][1], c0[2], r2["height"]))]
    ch = json.loads((sd / "search_rank1_widest_range" / "open_b45_selected.json").read_text())["chosen"]
    stances.append(("rank 1's finder stance", (ch["x"], ch["y"], math.radians(ch["heading_deg"]), ch["q"])))
    for v in args.variants:
        f = sd / f"search_{v}_coverage" / "open_b45_selected.json"
        if f.exists() and json.loads(f.read_text())["chosen"]:
            ch = json.loads(f.read_text())["chosen"]
            stances.append((f"{v}'s finder stance", (ch["x"], ch["y"], math.radians(ch["heading_deg"]), ch["q"])))
    cells, rows_json = {}, []
    for pi, (pname, q) in enumerate(poses):
        HPC.set_home(q)
        search = HPS.Search()
        ev = search.ev
        tol = tolerance_fn(ev, c0[2])
        for si, (sname, st) in enumerate(stances):
            res, img = measure(ev, st, tol, search)
            cells[(si, pi)] = (res, img)
            rows_json.append({"pose": pname, "q_deg": list(map(float, q)), "stance_name": sname, **res})
            print(f"{pname} at {sname} {np.round(st, 3).tolist()}: arms {100 * res['arm_frac']:.1f} % (hands {100 * res['hand_frac']:.1f} %), beaker hidden {100 * res['beaker_hidden']:.1f} %, "
                  f"hotplate hidden {100 * res['hotplate_hidden']:.1f} %, framing slack {100 * res['framing_slack']:.1f} %, requirements met: {res['requirements_met']}, gripper yaw {res['gripper_yaw_deg']:+.1f} deg", flush=True)
        del search, ev
        gc.collect()
    # the image: one row per stance, one column per pose
    big = []
    for si, (sname, st) in enumerate(stances):
        row = []
        for pi, (pname, q) in enumerate(poses):
            res, img = cells[(si, pi)]
            im = cv2.cvtColor(cv2.resize(img, CELL), cv2.COLOR_RGB2BGR)
            tag(im, f"{pname}", 6, 26, 0.7)
            ok = res["requirements_met"]
            lines = [(f"arms {100 * res['arm_frac']:.1f} %  hands {100 * res['hand_frac']:.1f} %", (255, 255, 255)),
                     (f"beaker hid {100 * res['beaker_hidden']:.1f} %  hotplate hid {100 * res['hotplate_hidden']:.1f} %", (60, 190, 60) if occlusion_ok({"beaker_hidden_frac": res["beaker_hidden"], "hotplate_hidden_frac": res["hotplate_hidden"]}) else (80, 80, 240)),
                     (f"framing {100 * res['framing_slack']:.1f} %  requirements {'met' if ok else 'NOT met'}", (60, 190, 60) if ok else (80, 80, 240))]
            for k, (text, col) in enumerate(lines):
                (w, h), base = cv2.getTextSize(text, cv2.FONT_HERSHEY_SIMPLEX, 0.5, 1)
                y = CELL[1] - 8 - 20 * (len(lines) - 1 - k)
                cv2.rectangle(im, (4, y - h - 4), (w + 12, y + base + 2), (30, 30, 30), -1)
                cv2.putText(im, text, (8, y), cv2.FONT_HERSHEY_SIMPLEX, 0.5, col, 1, cv2.LINE_AA)
            row.append(np.pad(im, ((0, 4), (0, 4), (0, 0))))
        banner = np.full((34, row[0].shape[1] * len(row), 3), 38, np.uint8)
        cv2.putText(banner, f"{sname}: x {st[0]:.3f} y {st[1]:.3f} pedestal {st[3]:.3f}   (arms tinted red; arm coverage = share of the image)", (8, 23), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (255, 255, 255), 1, cv2.LINE_AA)
        big += [banner, np.hstack(row)]
    img = np.vstack(big)
    tmp = out / "coverage.png.tmp.png"
    cv2.imwrite(str(tmp), img)
    assert cv2.imread(str(tmp)) is not None and cv2.imread(str(tmp)).shape == img.shape
    os.replace(tmp, out / "coverage.png")
    SFM.save(out / "coverage.json", rows_json)
    md = ["| stance | pose | arm coverage | hands | beaker hidden | hotplate hidden | framing slack | home clearance mm | placed beaker mm | neck spread | gripper yaw | requirements met |", "|---|---|---|---|---|---|---|---|---|---|---|---|"]
    for r in rows_json:
        md.append(f"| {r['stance_name']} ({r['stance'][0]:.3f}, {r['stance'][1]:.3f}, {r['stance'][3]:.3f}) | {r['pose']} | {100 * r['arm_frac']:.1f} % | {100 * r['hand_frac']:.1f} % | {100 * r['beaker_hidden']:.1f} % | "
                  f"{100 * r['hotplate_hidden']:.1f} % | {100 * r['framing_slack']:.1f} % | {r['home_clearance_mm']:.0f} | {r['placed_beaker_mm']:.0f} | {r['neck_spread']:.3f} | {r['gripper_yaw_deg']:+.1f} | {'yes' if r['requirements_met'] else 'no'} |")
    (out / "coverage.md").write_text("\n".join(md) + "\n")
    print("\n".join(md))
    print(f"COVERAGE DONE {out / 'coverage.png'}", flush=True)


if __name__ == "__main__":
    main()
